//! Editable starter documents generated by FigCraft v0.17.0's template builders.
use super::*;
use std::{collections::BTreeSet, io::Read, sync::OnceLock};

const STARTERS: &[(&str, &str, &str, &str, &str)] = &[
    (
        "mobile-app",
        "Mobile app",
        "Four screens of a trail app with components and a prototype flow",
        "app",
        "390 × 844",
    ),
    (
        "landing-page",
        "Landing page",
        "A responsive product page: hero, features, figures, a quote and a footer",
        "website",
        "1440 wide",
    ),
    (
        "dashboard",
        "Dashboard",
        "An analytics screen on a grid: figures, charts drawn from vectors and a table",
        "app",
        "1440 × 960",
    ),
    (
        "design-system",
        "Design system starter",
        "Colour and text styles, Light and Dark variables, buttons, inputs and cards",
        "kit",
        "2 pages",
    ),
    (
        "wireframe-kit",
        "Wireframe kit",
        "Greyscale components and two example screens to sketch a flow with",
        "kit",
        "390 and 1280 wide",
    ),
    (
        "social-posts",
        "Social post sizes",
        "One announcement in five common sizes: square, portrait, story, link and banner",
        "media",
        "5 sizes",
    ),
    (
        "slides",
        "Presentation slides",
        "A title, an agenda, a big figure, a chart and a closing slide",
        "media",
        "1920 × 1080",
    ),
    (
        "icon-set",
        "Icon set starter",
        "Icon components on a 24 px grid with keylines and a size preview",
        "kit",
        "24 × 24",
    ),
];

fn list() -> Value {
    json!(
        STARTERS
            .iter()
            .map(|(id, name, description, kind, size)| json!({
                "id":id,"name":name,"description":description,"kind":kind,"size":size,
            }))
            .collect::<Vec<_>>()
    )
}

fn documents() -> Result<&'static Value> {
    static DATA: OnceLock<std::result::Result<Value, String>> = OnceLock::new();
    DATA.get_or_init(|| {
        let mut bytes = Vec::new();
        flate2::read::GzDecoder::new(include_bytes!("template_assets/starters.json.gz").as_slice())
            .take(4 * 1024 * 1024)
            .read_to_end(&mut bytes)
            .map_err(|e| e.to_string())?;
        serde_json::from_slice(&bytes).map_err(|e| e.to_string())
    })
    .as_ref()
    .map_err(|error| {
        EngineError::new(
            "corrupt_state",
            format!("Invalid bundled starters: {error}"),
        )
    })
}

impl ToolRouter {
    pub(super) fn fig_starter_command(
        &self,
        session: &str,
        name: &str,
        params: &Value,
    ) -> Result<Value> {
        if name == "template.list" {
            return Ok(list());
        }
        let Some(template) = params.get("template") else {
            return Ok(json!({"templates":list()}));
        };
        let id = template
            .as_str()
            .filter(|id| STARTERS.iter().any(|starter| starter.0 == *id))
            .ok_or_else(|| EngineError::invalid("template must be an id from template.list"))?;
        let mut content = convert(&documents()?[id])?;
        if let Some(name) = params["name"]
            .as_str()
            .map(str::trim)
            .filter(|name| !name.is_empty())
        {
            content.title = name.to_owned();
        }
        let title = content.title.clone();
        let doc = self.workspace.create(session, &title, Some(content))?;
        self.context_from(session, &doc)?;
        self.fig_record_tab(session, json!({"id":external_id(&doc.id)}))?;
        let tabs = self.fig_tabs.lock().unwrap();
        let index = tabs
            .get(session)
            .and_then(|tabs| tabs.iter().position(|id| id == &doc.id))
            .unwrap_or(0);
        Ok(json!({"index":index,"template":id,"id":external_id(&doc.id),"name":doc.title}))
    }
}

fn rank(index: usize) -> String {
    format!("{:032x}", (index as u128 + 1) << 112)
}

fn convert(file: &Value) -> Result<DocumentContent> {
    let records = file["nodes"]
        .as_object()
        .ok_or_else(|| EngineError::invalid("Starter has no nodes"))?;
    let ids = records
        .iter()
        .filter_map(|(_, node)| node["id"].as_u64())
        .map(|id| (id, omc_model::new_id("node")))
        .collect::<BTreeMap<_, _>>();
    let get = |id: &Value| id.as_u64().and_then(|id| ids.get(&id)).map(String::as_str);
    let mut result = DocumentContent {
        title: string(file, "name")?.into(),
        pages: Vec::new(),
        nodes: BTreeMap::new(),
        metadata: Properties::new(),
    };
    let mut pending = Vec::new();
    for (index, id) in values(&file["pages"]).iter().enumerate() {
        let raw = get(id).ok_or_else(|| EngineError::invalid("Starter page has no ID"))?;
        let name = records[&id.to_string()]["name"].as_str().unwrap_or("Page");
        let mut page = omc_model::Page::new(name, raw);
        page.rank = rank(index);
        result.pages.push(page);
        pending.push((id.as_u64().unwrap(), None, index));
    }
    while let Some((wire, parent, index)) = pending.pop() {
        let source = &records[&wire.to_string()];
        let kind = match source["type"].as_str().unwrap_or_default() {
            "page" | "frame" | "componentSet" => NodeKind::Frame,
            "rectangle" => NodeKind::Rect,
            "ellipse" => NodeKind::Ellipse,
            "text" => NodeKind::Text,
            "vector" => NodeKind::Path,
            "component" => NodeKind::Component,
            "instance" => NodeKind::Instance,
            _ => return Err(EngineError::invalid("Unknown starter node type")),
        };
        let mut node = Node::new(kind);
        node.id = ids[&wire].clone();
        node.parent_id = parent.and_then(|id| ids.get(&id).cloned());
        if let Some(id) = node.parent_id.as_ref() {
            node.home_shard = result.nodes[id].home_shard.clone();
        }
        node.rank = rank(index);
        node.properties = layer_properties(source, &get)?;
        if source["type"] == "componentSet" {
            node.properties.insert("isVariantSet".into(), json!(true));
            node.properties
                .insert("variantSetId".into(), json!(node.id));
        }
        if kind == NodeKind::Component
            && parent.is_some_and(|p| records[&p.to_string()]["type"] == "componentSet")
        {
            node.properties
                .insert("variantSetId".into(), json!(node.parent_id));
            let axes = node
                .string("name")
                .unwrap_or_default()
                .split(',')
                .filter_map(|pair| pair.split_once('='))
                .map(|(name, value)| json!({"name":name.trim(),"value":value.trim()}))
                .collect::<Vec<_>>();
            node.properties
                .insert("variantProperties".into(), json!(axes));
        }
        if kind == NodeKind::Instance
            && let Some(component) = get(&source["component"])
        {
            node.properties
                .insert("componentId".into(), json!(component));
            if source["props"].is_object() {
                node.properties
                    .insert("componentProperties".into(), source["props"].clone());
            }
            let mut overrides = serde_json::Map::new();
            let mut descendants = values(&source["children"]).iter().collect::<Vec<_>>();
            while let Some(child) = descendants.pop() {
                let child = &records[&child.to_string()];
                if let Some(origin) = get(&child["source"]) {
                    overrides.insert(origin.into(), json!(layer_properties(child, &get)?));
                }
                descendants.extend(values(&child["children"]));
            }
            node.properties
                .insert("overrides".into(), Value::Object(overrides));
        } else {
            pending.extend(
                values(&source["children"])
                    .iter()
                    .enumerate()
                    .filter_map(|(index, id)| Some((id.as_u64()?, Some(wire), index))),
            );
        }
        result.nodes.insert(node.id.clone(), node);
    }
    catalogs(file, &mut result.metadata)?;
    result.validate().map_err(EngineError::invalid)?;
    Ok(result)
}

fn values(value: &Value) -> &[Value] {
    value.as_array().map_or(&[], Vec::as_slice)
}

fn layer_properties<'a>(
    source: &Value,
    get: &impl Fn(&Value) -> Option<&'a str>,
) -> Result<Properties> {
    let mut out = Properties::from([("name".into(), source["name"].clone())]);
    if source["type"] == "page" {
        if let Some(color) = color(&source["background"]) {
            out.insert("fill".into(), json!(color));
        }
        let flows=values(&source["flows"]).iter().filter_map(|flow|Some(json!({
            "name":flow["name"],"start":get(&flow["start"])?,"description":flow["description"],
        }))).collect::<Vec<_>>();
        if !flows.is_empty() {
            out.insert("prototypeFlows".into(), json!(flows));
        }
        return Ok(out);
    }
    for (key, target) in [
        ("width", "width"),
        ("height", "height"),
        ("opacity", "opacity"),
        ("clip", "clipContent"),
        ("visible", "visible"),
        ("locked", "locked"),
        ("description", "description"),
    ] {
        if !source[key].is_null() {
            out.insert(target.into(), source[key].clone());
        }
    }
    if let Some(matrix) = source["transform"]
        .as_array()
        .filter(|array| array.len() == 6)
    {
        out.insert("x".into(), matrix[4].clone());
        out.insert("y".into(), matrix[5].clone());
        if matrix[..4].iter().map(|value| value.as_f64()).ne([
            Some(1.),
            Some(0.),
            Some(0.),
            Some(1.),
        ]) {
            out.insert(
                "transform".into(),
                json!([matrix[0], matrix[2], matrix[1], matrix[3], 0, 0]),
            );
        }
    }
    if let Some(radius) = source["corners"]["radii"][0]
        .as_f64()
        .filter(|radius| *radius > 0.)
    {
        out.insert("radius".into(), json!(radius));
    }
    for (wire, key) in [("fills", "fills"), ("strokes", "strokes")] {
        if source.get(wire).is_some() {
            let mut stack = paints(&source[wire]);
            if wire == "strokes" {
                for paint in &mut stack {
                    add_stroke_options(paint, &source["stroke"]);
                }
            }
            out.insert(key.into(), json!(stack));
        }
    }
    if source["type"] == "vector" {
        out.insert("path".into(), json!(network_path(&source["network"])));
        if values(&source["network"]["regions"])
            .iter()
            .any(|region| region["winding"] == "evenOdd")
        {
            out.insert("fillRule".into(), json!("evenodd"));
        }
    }
    if source["type"] == "text" {
        out.insert("text".into(), source["characters"].clone());
        out.extend(text_style(&source["style"]));
        if let Some(align) = source["align_h"].as_str() {
            out.insert(
                "textAlign".into(),
                json!(match align {
                    "center" => "center",
                    "right" => "right",
                    "justify" => "justify",
                    _ => "left",
                }),
            );
        }
    }
    if !source["layout"].is_null() {
        out.insert("layout".into(), layout(&source["layout"]));
    }
    let child = &source["child_layout"];
    let mut css = serde_json::Map::new();
    if child["absolute"] == true {
        css.insert("position".into(), json!("absolute"));
    }
    for (key, css_key) in [
        ("min_w", "min-width"),
        ("max_w", "max-width"),
        ("min_h", "min-height"),
        ("max_h", "max-height"),
    ] {
        if let Some(value) = child[key].as_f64() {
            css.insert(css_key.into(), json!(format!("{value}px")));
        }
    }
    for (key, css_key, span) in [
        ("grid_column", "grid-column", "grid_column_span"),
        ("grid_row", "grid-row", "grid_row_span"),
    ] {
        if let Some(start) = child[key].as_u64() {
            css.insert(
                css_key.into(),
                json!(format!(
                    "{} / span {}",
                    start + 1,
                    child[span].as_u64().unwrap_or(1).max(1)
                )),
            );
        }
    }
    if !css.is_empty() {
        out.insert("style".into(), Value::Object(css));
    }
    for (key, destination) in [
        ("fill", "fillStyleId"),
        ("stroke", "strokeStyleId"),
        ("text", "textStyleId"),
    ] {
        if let Some(id) = source["styles"][key].as_str() {
            out.insert(destination.into(), json!(id));
        }
    }
    if let Some(bound) = source["bound"].as_object() {
        let mut bindings = serde_json::Map::new();
        for (key, id) in bound {
            if key == "fill" || key == "stroke" {
                let dest = if key == "fill" { "fills" } else { "strokes" };
                if let Some(paint) = out
                    .get_mut(dest)
                    .and_then(Value::as_array_mut)
                    .and_then(|paints| paints.first_mut())
                {
                    paint["color"] = json!({"$token":id});
                }
            } else {
                let field = if key == "characters" { "text" } else { key };
                bindings.insert(field.into(), json!({"$token":id}));
            }
        }
        if !bindings.is_empty() {
            out.insert("figcraftVariableBindings".into(), Value::Object(bindings));
        }
    }
    if source["var_modes"].is_object() {
        out.insert("figcraftVariableModes".into(), source["var_modes"].clone());
    }
    let shadows=values(&source["effects"]).iter().filter(|effect|effect["type"]=="dropShadow").map(|effect|json!({
        "x":effect["offset"][0],"y":effect["offset"][1],"blur":effect["radius"],"spread":effect["spread"],
        "color":color(&effect["color"]).unwrap_or_else(||"#00000020".into()),"visible":effect["visible"],
    })).collect::<Vec<_>>();
    if !shadows.is_empty() {
        out.insert("shadows".into(), json!(shadows));
    }
    if source["prop_refs"].is_object() {
        out.insert("componentPropertyRefs".into(), source["prop_refs"].clone());
    }
    if source["type"] == "component"
        && let Some(props) = source["props"].as_object()
    {
        let defs = props
            .iter()
            .filter_map(|(name, spec)| {
                let kind = spec["type"].as_str()?;
                let kind = match kind {
                    "boolean" => "boolean",
                    "text" => "text",
                    "instanceSwap" | "swap" => "swap",
                    _ => return None,
                };
                let default = if kind == "swap" {
                    get(&spec["default"]).map_or(Value::Null, |id| json!(id))
                } else {
                    spec["default"].clone()
                };
                Some(json!({"id":name,"name":name,"type":kind,"default":default}))
            })
            .collect::<Vec<_>>();
        out.insert("componentPropertyDefinitions".into(), json!(defs));
    }
    let interactions=values(&source["interactions"]).iter().filter_map(|interaction| {
        if interaction["trigger"]["type"]!="onClick" {return None;}
        let dest=get(&interaction["actions"][0]["dest"])?;
        Some(json!({"trigger":{"type":"onClick"},"actions":[{"type":"navigate","dest":dest}],
            "transition":interaction["transition"],"durationMs":interaction["duration_ms"],"easing":interaction["easing"],
        }))
    }).collect::<Vec<_>>();
    if let Some(first) = interactions.first() {
        out.insert(
            "prototypeClickTargetId".into(),
            first["actions"][0]["dest"].clone(),
        );
        out.insert("prototypeInteractions".into(), json!(interactions));
    }
    Ok(out)
}

fn color(value: &Value) -> Option<String> {
    let channel = |key: &str| {
        value[key]
            .as_f64()
            .map(|value| (value.clamp(0., 1.) * 255.).round() as u8)
    };
    let (r, g, b, a) = (
        channel("r")?,
        channel("g")?,
        channel("b")?,
        channel("a").unwrap_or(255),
    );
    Some(if a == 255 {
        format!("#{r:02x}{g:02x}{b:02x}")
    } else {
        format!("#{r:02x}{g:02x}{b:02x}{a:02x}")
    })
}

fn paints(value: &Value) -> Vec<Value> {
    values(value)
        .iter()
        .filter_map(|paint| {
            let mut native = paint.clone();
            if paint["type"] == "gradient" {
                native["type"] = paint["kind"].clone();
                for stop in native["stops"].as_array_mut()? {
                    stop["color"] = json!(color(&stop["color"])?);
                }
            } else {
                native["color"] = json!(color(&paint["color"])?);
            }
            Some(native)
        })
        .collect()
}

fn add_stroke_options(paint: &mut Value, stroke: &Value) {
    for (key, dest) in [
        ("weight", "width"),
        ("align", "align"),
        ("join", "join"),
        ("miter_limit", "miterLimit"),
        ("dashes", "dash"),
    ] {
        if !stroke[key].is_null() {
            paint[dest] = stroke[key].clone();
        }
    }
    if matches!(stroke["cap_start"].as_str(), Some("round" | "square")) {
        paint["cap"] = stroke["cap_start"].clone();
    }
}

fn text_style(style: &Value) -> Properties {
    let mut out = Properties::new();
    for (key, dest) in [("font_family", "fontFamily"), ("font_size", "fontSize")] {
        if !style[key].is_null() {
            out.insert(dest.into(), style[key].clone());
        }
    }
    if let Some(font) = style["font_style"].as_str() {
        let lower = font.to_ascii_lowercase();
        let weight = if lower.contains("black") {
            900
        } else if lower.contains("extra bold") {
            800
        } else if lower.contains("semi") {
            600
        } else if lower.contains("bold") {
            700
        } else if lower.contains("medium") {
            500
        } else if lower.contains("light") {
            300
        } else {
            400
        };
        out.insert("fontWeight".into(), json!(weight));
        if lower.contains("italic") {
            out.insert("fontStyle".into(), json!("italic"));
        }
    }
    for (key, dest) in [
        ("line_height", "lineHeight"),
        ("letter_spacing", "letterSpacing"),
    ] {
        if let Some(value) = style[key]["value"].as_f64() {
            let unit = if style[key]["unit"] == "percent" {
                "%"
            } else {
                "px"
            };
            out.insert(dest.into(), json!(format!("{value}{unit}")));
        }
    }
    out
}

fn layout(source: &Value) -> Value {
    let align = |value: &Value| match value.as_str() {
        Some("center") => "center",
        Some("max") => "flex-end",
        Some("spaceBetween") => "space-between",
        Some("stretch") => "stretch",
        _ => "flex-start",
    };
    let mut layout = json!({
        "type":if source["mode"]=="grid"{"grid"}else{"flex"},
        "direction":if source["mode"]=="vertical"{"column"}else{"row"},
        "gap":source["gap"],"padding":source["padding"],"alignItems":align(&source["cross_align"]),
        "justifyContent":align(&source["main_align"]),"wrap":source["wrap"],
    });
    if source["mode"] == "grid" {
        for (key, dest, count) in [
            ("column_tracks", "columns", "grid_columns"),
            ("row_tracks", "rows", "grid_rows"),
        ] {
            let tracks = values(&source[key])
                .iter()
                .map(|track| {
                    let value = track["value"].as_f64().unwrap_or(1.);
                    match track["sizing"].as_str() {
                        Some("fixed") => format!("{value}px"),
                        Some("hug") => "auto".into(),
                        _ => format!("{}fr", value.max(0.01)),
                    }
                })
                .collect::<Vec<_>>();
            layout[dest] = json!(if tracks.is_empty() {
                vec!["1fr".to_owned(); source[count].as_u64().unwrap_or(1) as usize]
            } else {
                tracks
            });
        }
    }
    layout
}

fn network_path(network: &Value) -> String {
    use std::fmt::Write;
    let vertices = values(&network["vertices"]);
    let segments = values(&network["segments"]);
    let mut used = BTreeSet::new();
    let mut path = String::new();
    let draw = |path: &mut String, used: &mut BTreeSet<usize>, indices: &[usize], closed: bool| {
        let mut last = None;
        for &index in indices {
            let Some(segment) = segments.get(index) else {
                continue;
            };
            let (Some(mut a), Some(mut b)) = (
                segment["a"].as_u64().map(|n| n as usize),
                segment["b"].as_u64().map(|n| n as usize),
            ) else {
                continue;
            };
            let (mut ta, mut tb) = (&segment["ta"], &segment["tb"]);
            if last == Some(b) && last != Some(a) {
                std::mem::swap(&mut a, &mut b);
                std::mem::swap(&mut ta, &mut tb);
            }
            let (Some(from), Some(to)) = (vertices.get(a), vertices.get(b)) else {
                continue;
            };
            let (x, y) = (
                from["x"].as_f64().unwrap_or(0.),
                from["y"].as_f64().unwrap_or(0.),
            );
            let (u, v) = (
                to["x"].as_f64().unwrap_or(0.),
                to["y"].as_f64().unwrap_or(0.),
            );
            if last != Some(a) {
                let _ = write!(path, "M{x} {y}");
            }
            let tangents = [
                ta[0].as_f64(),
                ta[1].as_f64(),
                tb[0].as_f64(),
                tb[1].as_f64(),
            ]
            .map(|x| x.unwrap_or(0.));
            if tangents.iter().all(|&x| x == 0.) {
                let _ = write!(path, "L{u} {v}");
            } else {
                let _ = write!(
                    path,
                    "C{} {} {} {} {u} {v}",
                    x + tangents[0],
                    y + tangents[1],
                    u + tangents[2],
                    v + tangents[3]
                );
            }
            used.insert(index);
            last = Some(b);
        }
        if closed {
            path.push('Z');
        }
    };
    for region in values(&network["regions"]) {
        for loop_ in values(&region["loops"]) {
            let indices = values(loop_)
                .iter()
                .filter_map(|segment| segment.as_u64().map(|n| n as usize))
                .collect::<Vec<_>>();
            draw(&mut path, &mut used, &indices, true);
        }
    }
    let remaining = (0..segments.len())
        .filter(|index| !used.contains(index))
        .collect::<Vec<_>>();
    draw(&mut path, &mut used, &remaining, false);
    path
}

fn catalog(out: &mut Properties, kind: &str, id: &str, entry: Value) {
    if let Some(entry) = entry.as_object() {
        for (key, value) in entry {
            out.insert(format!("{kind}/{id}/{key}"), value.clone());
        }
    }
}

fn catalogs(file: &Value, out: &mut Properties) -> Result<()> {
    for style in values(&file["styles"]) {
        let id = string(style, "id")?;
        let value = if style["type"] == "text" {
            json!(text_style(&style["style"]))
        } else {
            json!(paints(&style["paints"]))
        };
        catalog(
            out,
            "styles",
            id,
            json!({
                "name":style["name"],"type":if style["type"]=="text"{"text"}else{"paint"},
                "description":style["description"],"value":value,
            }),
        );
    }
    let mut modes = BTreeMap::new();
    for collection in values(&file["variables"]["collections"]) {
        let id = string(collection, "id")?;
        let default = collection["modes"][0]["id"].clone();
        modes.insert(id, default.clone());
        catalog(
            out,
            "figcraftCollections",
            id,
            json!({"name":collection["name"],"modes":collection["modes"],"defaultModeId":default}),
        );
    }
    for token in values(&file["variables"]["variables"]) {
        let id = string(token, "id")?;
        let collection = string(token, "collection")?;
        let values = token["values"]
            .as_object()
            .into_iter()
            .flatten()
            .filter_map(|(mode, value)| {
                let value = match value["type"].as_str()? {
                    "color" => json!(color(&value["value"])?),
                    "alias" => json!({"$token":value["value"]}),
                    _ => value["value"].clone(),
                };
                Some((mode.clone(), value))
            })
            .collect::<serde_json::Map<_, _>>();
        let default = modes
            .get(collection)
            .and_then(Value::as_str)
            .and_then(|mode| values.get(mode))
            .cloned()
            .unwrap_or(Value::Null);
        let kind = if token["resolvedType"] == "float" {
            "number"
        } else {
            token["resolvedType"].as_str().unwrap_or("string")
        };
        catalog(
            out,
            "tokens",
            id,
            json!({"name":token["name"],"type":kind,"description":token["description"],
            "collectionId":collection,"value":default,"modes":values}),
        );
    }
    Ok(())
}
